	public override void Update()
	{
		if (!eventStarted && !LoadingScreen.loading && GameController.activePlayers.Length > 0)
		{
			eventStarted = true;
			AchievementManager.UnlockAchievement(Achievement.CompleteTutorial);
			StartCoroutine(WakeUpPlayers());
