using System.Collections;
using Chaos.AnimatorExtensions;
using UnityEngine;

public class MuseumSignatureExample : MonoBehaviour
{
	public float repeatTime = 5f;

	private ChaosQuickStopwatch repeatStopwatch = new ChaosQuickStopwatch(5f);

	private Animator anim;

	private SpriteRenderer spriteRenderer;

	public Transform spawnTransform;

	private OverdriveEffects overdriveEffects;

	private Animator[] ghoulAnims = new Animator[3];

	private Material[] ghoulMats = new Material[3];

	private Vector2 leftVector = new Vector2(-1f, -1f);

	private Vector2 rightVector = new Vector2(1f, -1f);

	private bool isRight;

	private Vector2 startVector;

	private Vector2 endVector;

	private ChaosQuickStopwatch ultStopwatch = new ChaosQuickStopwatch(2f);

	private float ultLerpValue;

	private ChaosQuickStopwatch ghoulStopwatch = new ChaosQuickStopwatch();

	private FireBlast currentFB;

	private WaitForSeconds waitForFlash = new WaitForSeconds(0.03f);

	private WaitForSeconds waitForOneSecond = new WaitForSeconds(1f);

	private bool ghoulsDead;

	private AudioSource odLoopAudio;

	private void Awake()
	{
		anim = GetComponent<Animator>();
		spriteRenderer = base.transform.Find("PlayerSprite").GetComponent<SpriteRenderer>();
		spriteRenderer.material = new Material(spriteRenderer.material);
		spriteRenderer.material.SetFloat("_PaletteIndex", 15f);
		for (int i = 0; i < 3; i++)
		{
			Transform transform = base.transform.parent.Find("Ghoul" + i);
			ghoulAnims[i] = transform.GetComponent<Animator>();
			ghoulMats[i] = transform.Find("EnemySprite").GetComponent<SpriteRenderer>().material;
		}
	}

	private void Start()
	{
		overdriveEffects = Globals.ChaosInst<OverdriveEffects>(OverdriveEffects.Prefab, transform);
		overdriveEffects.SetFollowTransform(transform);
		repeatStopwatch.SetDelay(repeatTime);
		if (spawnTransform == null)
		{
			spawnTransform = transform;
		}
	}

	private void Update()
	{
		if (!repeatStopwatch.IsRunning)
		{
			repeatStopwatch.IsRunning = true;
			StartCoroutine(HandleFireBlast());
		}
	}

	private IEnumerator HandleFireBlast()
	{
		anim.Play("RunDown");
		for (int i = 0; i < 3; i++)
		{
			ghoulAnims[i].Play("IdleDown");
			ghoulMats[i].SetFloat("_FlashAmount", 1f);
		}
		yield return waitForFlash;
		float fadeInTime = 0.25f;
		while (fadeInTime > 0f)
		{
			fadeInTime -= Time.deltaTime;
			for (int j = 0; j < 3; j++)
			{
				ghoulMats[j].SetFloat("_FlashAmount", Mathf.Lerp(0f, 1f, fadeInTime * 4f));
			}
			yield return null;
		}
		for (int k = 0; k < 3; k++)
		{
			ghoulAnims[k].Play("RunRight");
			ghoulMats[k].SetFloat("_FlashAmount", 0f);
		}
		yield return waitForOneSecond;
		anim.Play("PBAoEDown", -1, 0f);
		while (!anim.AnimPlayed(0.3f))
		{
			yield return null;
		}
		overdriveEffects.Burst(80, local: true, activation: true, shakeCamera: false);
		isRight = !isRight;
		if (isRight)
		{
			startVector = rightVector;
			endVector = leftVector;
		}
		else
		{
			startVector = leftVector;
			endVector = rightVector;
		}
		currentFB = Globals.ChaosInst<FireBlast>(FireBlast.Prefab, spawnTransform, spawnTransform.position, Globals.GetRotationQuaternion(startVector));
		currentFB.CircleBlast();
		ultStopwatch.IsRunning = true;
		ghoulStopwatch.IsRunning = true;
		ghoulsDead = false;
		while (ultStopwatch.IsRunning)
		{
			ultLerpValue = ultStopwatch.TimePercentage * 2f;
			if (currentFB != null)
			{
				if (ultLerpValue <= 1f)
				{
					currentFB.transform.localEulerAngles = Globals.GetRotationVector(Vector2.Lerp(startVector, endVector, ultLerpValue));
				}
				else
				{
					currentFB.transform.localEulerAngles = Globals.GetRotationVector(Vector2.Lerp(endVector, startVector, ultLerpValue - 1f));
				}
			}
			if (!ghoulsDead && !ghoulStopwatch.IsRunning)
			{
				ghoulsDead = true;
				for (int l = 0; l < 3; l++)
				{
					ghoulAnims[l].Play("Dead");
				}
			}
			anim.Play("PBAoEDown", -1, 0.8f);
			PlayAudio();
			yield return null;
		}
		if (currentFB != null)
		{
			currentFB.EndAllAttacks();
		}
		StopAudio();
		while (!anim.AnimPlayed())
		{
			yield return null;
		}
		anim.Play("RunDown");
	}

	private void PlayAudio()
	{
		if (odLoopAudio == null || !odLoopAudio.isPlaying)
		{
			string audioID = "FireBlastODLoop";
			Transform originTrans = spawnTransform;
			odLoopAudio = SoundManager.PlayAudioWithDistance(audioID, null, originTrans);
		}
	}

	private void StopAudio()
	{
		if (odLoopAudio != null)
		{
			odLoopAudio.Stop();
			odLoopAudio = null;
			SoundManager.PlayAudioWithDistance("FireBlastODEnd", spawnTransform.position);
		}
	}
}
