	public bool AnimIsPlaying(float threshold = 1f)
	{
		return !anim.AnimPlayed(threshold);
	}

	public void StopAnnounce()
	{
		anim.Play("Idle");
	}

	public void Announce(string announceText, float duration = 0f, int fontSize = 60, Color? textColor = null, Color? lineColor = null, bool showUnderline = true, float animSpeed = 1f, float startingFrame = 0f, bool numberMode = false, Color? outlineColor = null, Vector3? lineScale = null, Color? underlineOutlineColor = null, float delayTime = 0f)
	{
		if (!(announceText == string.Empty))
		{
			StartCoroutine(Announcement(announceText, duration, fontSize, textColor, lineColor, showUnderline, animSpeed, startingFrame, numberMode, outlineColor, lineScale, underlineOutlineColor, delayTime));
		}
	}

	private IEnumerator Announcement(string announceText, float duration, int fontSize, Color? textColor, Color? lineColor, bool showUnderline, float animSpeed, float startingFrame, bool numberMode, Color? outlineColor, Vector3? lineScale, Color? underlineOutlineColor, float delayTime = 0f)
	{
		if (delayTime > 0f)
		{
			yield return new WaitForSeconds(delayTime);
		}
		int durationStopwatchID = -1;
		if (announcementInProgress)
		{
			announcementInProgress = false;
			for (int i = 0; i < 3; i++)
			{
				yield return null;
			}
		}
		announcementInProgress = true;
		anim.Play("Idle");
		yield return null;
		anim.speed = animSpeed;
		Text textToMod = stageTitleText;
		if (numberMode)
		{
			textToMod = numberText;
		}
		else
		{
			stageTitle = announceText;
		}
		textToMod.text = announceText;
		textToMod.fontSize = TextManager.GetAdjustedFontSize(fontSize);
		textToMod.color = (textColor.HasValue ? textColor.Value : Color.white);
		stageTitleUnderline.color = (lineColor.HasValue ? lineColor.Value : Color.white);
		stageTitleUnderline.enabled = showUnderline && !numberMode;
		if ((float)textToMod.fontSize >= 90f * TextManager.CurrentFontSizeMultiplier)
		{
			stageTitleUnderline.rectTransform.anchoredPosition = new Vector2(ogUnderlinePos.x, ogUnderlinePos.y - largeFontLineOffset * (float)textToMod.fontSize / (90f * TextManager.CurrentFontSizeMultiplier));
		}
		else
		{
			stageTitleUnderline.rectTransform.anchoredPosition = ogUnderlinePos;
		}
		if (!lineScale.HasValue)
		{
			stageTitleUnderline.rectTransform.localScale = Vector3.one;
		}
		else
		{
			stageTitleUnderline.rectTransform.localScale = lineScale.Value;
		}
		if (!outlineColor.HasValue)
		{
			stageTitleOutline.effectColor = Color.clear;
		}
		else
		{
			stageTitleOutline.effectColor = outlineColor.Value;
		}
		if (!underlineOutlineColor.HasValue)
		{
			underlineOutline.effectColor = Color.clear;
		}
		else
		{
			underlineOutline.effectColor = underlineOutlineColor.Value;
		}
		if (announcementInProgress)
		{
			durationStopwatchID = ChaosStopwatch.Begin(duration);
			if (numberMode)
			{
				anim.Play("AnnounceNumber", -1, startingFrame);
			}
			else
			{
				anim.Play("Announce", -1, startingFrame);
			}
			yield return null;
		}
		while (announcementInProgress && anim.GetAnimTime() < 0.3f)
		{
			yield return null;
		}
		while (announcementInProgress && !ChaosStopwatch.Check(durationStopwatchID))
		{
			anim.Play("Announce", -1, 0.55f);
			yield return null;
		}
		announcementInProgress = false;
	}

