		anim = GetComponent<Animator>();
	}

	private void Start()
	{
		Vector3 vector = new Vector3(0f, 0f, -10f);
		masterMixer.FindSnapshot("TitleScreen").TransitionTo(0f);
		Camera.main.transform.position = vector;
		GameController.cameraController.spawnPos = vector;
		GameController.cameraController.disablePlayerTracking = true;
		GameController.cameraController.lockToSpawnPos = true;
		if (CharacterSelectUI.P1CharacterSelectUI != null)
		{
			CharacterSelectUI.P1CharacterSelectUI.Disable(releaseInputDevice: true);
		}
		if (CharacterSelectUI.P2CharacterSelectUI != null)
		{
			CharacterSelectUI.P2CharacterSelectUI.Disable(releaseInputDevice: true);
		}
		GameController.coopOn = false;
		GameController.TogglePvpMode(pvpStatus: false);
		GameUI.BroadcastNoticeMessage(" ");
		if (GameController.stageTitleUI != null)
		{
			GameController.stageTitleUI.StopAnnounce();
		}
		GameUI.SetMoneyStatus(givenStatus: false);
		SelectMenuIndex(currentMenuIndex);
		currentBGIndex = GameDataManager.gameVars.GetIntValue(GameVarsKey.TitleBG);
		SetectBGIndex(currentBGIndex);
		startCompleted = true;
		AchievementManager.Initialize(GameController.Instance, forceOverride: true);
	}

	private void Update()
	{
		HandleMenuStates();
		if (currentMenuIndex == multiplayerOptIndex || currentMenuIndex == versusOptIndex)
		{
			if (!AllowMultiplayer() && menuTextOpts[currentMenuIndex].color != Globals.uiNotSelectedColor)
			{
				ToggleMenuOption(menuTextOpts[currentMenuIndex], enable: true, disableSelected: true);
			}
			else if (AllowMultiplayer() && menuTextOpts[currentMenuIndex].color != Globals.uiSelectedColor)
			{
				ToggleMenuOption(menuTextOpts[currentMenuIndex]);
			}
		}
	}

	public void HandleMenuStates()
	{
		bool flag = false;
		switch (currentState)
		{
		case TitleScreenState.Menu:
			HandleNavigation();
			break;
		case TitleScreenState.Standby:
			HandleBGChange();
			if (InputController.GetAnyDeviceButtonDown("Confirm") != null || InputController.GetAnyDeviceButtonDown("Skill0") != null || InputController.GetAnyDeviceButtonDown("Skill1") != null || InputController.GetAnyDeviceButtonDown("Skill2") != null || InputController.GetAnyDeviceButtonDown("Skill3") != null || InputController.GetAnyDeviceButtonDown("Skill4") != null || InputController.GetAnyDeviceButtonDown("Skill5") != null || InputController.GetAnyDeviceButtonDown("Cancel") != null || InputController.GetAnyDeviceButtonDown("Interact") != null || InputController.GetAnyDeviceButtonDown("Menu") != null)
			{
				anim.Play("Menu", -1, 0f);
				SoundManager.PlayConfirmAudio();
				currentState = TitleScreenState.Menu;
				GameDataManager.SaveGameVars();
				FadeLogoAndExtra(fadeOut: false);
			}
			break;
		case TitleScreenState.Options:
			if (GameController.optionsMenu.releaseControlToParent)
			{
				GameController.optionsMenu.gameObject.SetActive(value: false);
				Show();
				SoundManager.BGMPaused = false;
				flag = true;
				if (GameController.resetGameDataQueued)
				{
					GameController.LoadLevel("InitialLoad");
				}
			}
			break;
		}
		if (flag)
		{
			currentState = TitleScreenState.Menu;
		}
	}

	public void HandleNavigation()
	{
		if (InputController.GetAnyDeviceDirection(InputDirection.Down))
		{
			currentMenuIndex++;
			SelectMenuIndex(currentMenuIndex, dirInput: true);
		}
		else if (InputController.GetAnyDeviceDirection(InputDirection.Up))
		{
			currentMenuIndex--;
			SelectMenuIndex(currentMenuIndex, dirInput: true);
		}
		if (InputController.GetAnyDeviceButtonDown("Confirm") != null)
		{
			ConfirmMenuOption();
		}
		else if (InputController.GetAnyDeviceButtonDown("Cancel") != null)
		{
			anim.Play("CancelMenu", -1, 0f);
			currentState = TitleScreenState.Standby;
		}
	}

	public void HandleBGChange()
	{
		if (!bgStopwatch.IsRunning)
		{
			if (InputController.GetAnyDeviceDirection(InputDirection.Left))
			{
				bgStopwatch.IsRunning = true;
				currentBGIndex--;
				SetectBGIndex(currentBGIndex);
				FadeLogoAndExtra(fadeOut: true);
			}
			else if (InputController.GetAnyDeviceDirection(InputDirection.Right))
			{
				bgStopwatch.IsRunning = true;
				currentBGIndex++;
				SetectBGIndex(currentBGIndex);
				FadeLogoAndExtra(fadeOut: true);
			}
		}
	}

	private void FadeLogoAndExtra(bool fadeOut)
	{
		float alpha = ((!fadeOut) ? 1f : 0f);
		logoImage.CrossFadeAlpha(alpha, 0.5f, ignoreTimeScale: false);
		extraLogo.CrossFadeAlpha(alpha, 0.5f, ignoreTimeScale: false);
		extraTwitter.CrossFadeAlpha(alpha, 0.5f, ignoreTimeScale: false);
		extraWebsite.CrossFadeAlpha(alpha, 0.5f, ignoreTimeScale: false);
		extraVersion.CrossFadeAlpha(alpha, 0.5f, ignoreTimeScale: false);
	}

	public void Show()
	{
		titleMenu.SetActive(value: true);
		logoImage.CrossFadeAlpha(1f, 0.5f, ignoreTimeScale: false);
		Text[] array = menuTextOpts;
		foreach (Text text in array)
		{
			text.CrossFadeAlpha(1f, 0.5f, ignoreTimeScale: false);
		}
	}

	public void Hide()
	{
		logoImage.CrossFadeAlpha(0f, 0.3f, ignoreTimeScale: false);
		Text[] array = menuTextOpts;
		foreach (Text text in array)
		{
			text.CrossFadeAlpha(0f, 0.3f, ignoreTimeScale: false);
		}
		titleMenu.SetActive(value: false);
	}

	public void SelectMenuIndex(int newIndex)
	{
		SelectMenuIndex(newIndex, false);
	}

	public void SelectMenuIndex(int newIndex, bool dirInput = false)
	{
		if ((GameController.mouseCursor.Hidden && !dirInput) || currentState != TitleScreenState.Menu)
		{
			return;
		}
		currentMenuIndex = newIndex;
		if (currentMenuIndex >= menuTextOpts.Length)
		{
			currentMenuIndex = 0;
		}
		else if (currentMenuIndex < 0)
		{
			currentMenuIndex = menuTextOpts.Length - 1;
		}
		for (int i = 0; i < menuTextOpts.Length; i++)
		{
			if (currentMenuIndex == i)
			{
				if (currentMenuIndex == multiplayerOptIndex && !AllowMultiplayer())
				{
					ToggleMenuOption(menuTextOpts[i], enable: true, disableSelected: true);
				}
				else if (currentMenuIndex == versusOptIndex && !AllowMultiplayer())
				{
					ToggleMenuOption(menuTextOpts[i], enable: true, disableSelected: true);
				}
				else
				{
					ToggleMenuOption(menuTextOpts[i]);
				}
			}
			else
			{
				ToggleMenuOption(menuTextOpts[i], enable: false);
			}
		}
		if (startCompleted)
		{
			SoundManager.PlayAudio("MenuMove");
		}
	}

	public void SetectBGIndex(int givenIndex)
	{
		currentBGIndex = (givenIndex + bgCount) % bgCount;
		GameDataManager.gameVars.SetValue(GameVarsKey.TitleBG, currentBGIndex);
		bgImageIndexZero = !bgImageIndexZero;
		bgImages[(!bgImageIndexZero) ? 1u : 0u].sprite = IconManager.GetBGSprite(currentBGIndex);
		if (bgImageIndexZero)
		{
			bgImages[0].CrossFadeAlpha(1f, 0.5f, ignoreTimeScale: false);
			bgImages[1].CrossFadeAlpha(0f, 0.5f, ignoreTimeScale: false);
		}
		else
		{
			bgImages[0].CrossFadeAlpha(0f, 0.5f, ignoreTimeScale: false);
			bgImages[1].CrossFadeAlpha(1f, 0.5f, ignoreTimeScale: false);
		}
	}

	public void ToggleMenuOption(Text menuOpt, bool enable = true, bool disableSelected = false)
	{
		if (enable)
		{
			menuOpt.color = Globals.uiSelectedColor;
			menuOpt.fontSize = TextManager.GetAdjustedFontSize(enabledFontSize);
			if (disableSelected)
			{
				menuOpt.color = Globals.uiNotSelectedColor;
			}
		}
		else
		{
			menuOpt.color = Globals.uiNotSelectedColor;
			menuOpt.fontSize = TextManager.GetAdjustedFontSize(disabledFontSize);
		}
	}

	public bool AllowMultiplayer()
	{
		return ReInput.controllers.controllerCount > 1;
	}

	public void ConfirmMenuOption()
	{
		if (currentState != TitleScreenState.Menu)
		{
			return;
		}
		switch (currentMenuIndex)
		{
		case 0:
			SoundManager.PlayConfirmAudio();
			StartGame();
			break;
		case 1:
			if (!AllowMultiplayer())
			{
				SoundManager.PlayAudio("MenuError");
				GlobalDialog.Display("titleScreen-connect2ndController");
			}
			else
			{
				SoundManager.PlayConfirmAudio();
				StartGame();
				GameController.coopOn = true;
			}
			break;
		case 2:
			if (!AllowMultiplayer())
			{
				SoundManager.PlayAudio("MenuError");
				GlobalDialog.Display("titleScreen-connect2ndController");
			}
			else
			{
				SoundManager.PlayConfirmAudio();
				StartGame(loadPvP: true);
				GameController.coopOn = true;
			}
			break;
		case 3:
			currentState = TitleScreenState.Options;
			GameController.optionsMenu.gameObject.SetActive(value: true);
			GameController.optionsMenu.releaseControlToParent = false;
			Hide();
			SoundManager.PlayConfirmAudio();
			break;
		case 4:
			Credits.transitionToTitle = true;
			GameController.LoadLevel("Credits");
			SoundManager.PlayConfirmAudio();
			break;
		case 5:
			SoundManager.PlayConfirmAudio();
			GameController.Quit();
			break;
		}
	}

	public void StartGame(bool loadPvP = false)
	{
		masterMixer.FindSnapshot("Default").TransitionTo(0.3f);
		GameController.cameraController.disablePlayerTracking = false;
		GameController.cameraController.spawnPos = new Vector3(0f, 0f, -10f);
		GameController.cameraController.lockToSpawnPos = false;
		GameController.ClearLevelStats(fullReset: true);
		GameUI.SetMoneyStatus(!loadPvP);
		if (loadPvP)
		{
			GameController.LoadLevel("PvP");
		}
		else if (!GameDataManager.gameData.tutorialCleared)
		{
			GameController.LoadLevel("Tutorial");
		}
		else
		{
			GameController.LoadLevel("PlayerRoom");
		}
	}
