using System;
using System.Collections.Generic;
using Chaos.ArrayExtensions;
using UnityEngine;
using UnityEngine.UI;

public class WardrobeUI : MonoBehaviour
{
	private class WardrobeObjRef
	{
		public Animator anim;

		public Transform outfitTrans;

		public Transform playerImageTrans;

		public Image[] playerImages;

		public Image playerImage;

		public Image[] outfitImageArray;

		public Image[] outfitBGImageArray;

		public Image[] outfitLockedImageArray;

		public Image[] outfitSelImageArray;

		public Animator[] outfitAnimArray;

		public Text infoTitleText;

		public Text infoDescText;
	}

	private static GameObject prefab;

	private Color curOutfitOutlineColor = new Color(1f, 1f, 1f, 0.75f);

	private Color outfitOutlineColor = new Color(0.207f, 0.18824f, 0.16863f);

	public bool isActive;

	private WardrobeObjRef wrRef;

	private Player player;

	private ChaosInputDevice inputDev;

	private Vector2 inputVector;

	private bool initNavDelayReset = true;

	private ChaosQuickStopwatch navTimer = new ChaosQuickStopwatch(0.3f);

	private ChaosQuickStopwatch autoNavTimer = new ChaosQuickStopwatch(0.15f);

	private string currentOutfitID;

	private int currentOutfitIndex;

	private int totalOutfitCount;

	private List<Outfit> availableOutfitList;

	private int offsetIndex;

	private int currentPlayerImageIndex;

	private float targetAngle;

	private float currentAngle;

	private float angleIncrement;

	private int rotationOrientation;

	private float rotationSpeed = (float)Math.PI * 3f;

	private float maxDistance = 4f;

	private Vector2 activationPosition = Vector2.zero;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/UI/WardrobeUI.prefab"));

	private void Start()
	{
		availableOutfitList = new List<Outfit>();
		foreach (KeyValuePair<string, Outfit> item in Outfit.OutfitDict)
		{
			availableOutfitList.Add(item.Value);
		}
		totalOutfitCount = availableOutfitList.Count;
		angleIncrement = (float)Math.PI * 2f / (float)totalOutfitCount;
		SetObjectReferences();
		Deactivate();
	}

	private void LoadOutfits()
	{
		currentOutfitID = player.playerData.outfitName;
		for (int i = 0; i < totalOutfitCount; i++)
		{
			if (availableOutfitList[i].outfitID == currentOutfitID)
			{
				currentOutfitIndex = i;
				break;
			}
		}
		for (int j = 0; j < totalOutfitCount; j++)
		{
			offsetIndex = (j + currentOutfitIndex) % totalOutfitCount;
			if (availableOutfitList[j].unlocked)
			{
				wrRef.outfitImageArray[j].material.SetFloat("_PaletteIndex", availableOutfitList[j].outfitColorIndex);
				wrRef.outfitSelImageArray[j].material.SetFloat("_PaletteIndex", availableOutfitList[j].outfitColorIndex);
				wrRef.outfitBGImageArray[j].enabled = true;
				wrRef.outfitImageArray[j].enabled = true;
				wrRef.outfitSelImageArray[j].enabled = true;
			}
			else
			{
				wrRef.outfitImageArray[j].material.SetFloat("_PaletteIndex", 22f);
				wrRef.outfitSelImageArray[j].material.SetFloat("_PaletteIndex", 22f);
				wrRef.outfitBGImageArray[j].enabled = false;
				wrRef.outfitImageArray[j].enabled = false;
				wrRef.outfitSelImageArray[j].enabled = false;
			}
		}
		currentAngle = (float)Math.PI / 2f + angleIncrement * (float)currentOutfitIndex;
		targetAngle = currentAngle;
		HandleSelectionRotation(currentAngle, currentOutfitIndex);
		UpdateOutfits(currentOutfitIndex);
		HandleOutfitOutlines(currentOutfitIndex);
	}

	private void SetObjectReferences()
	{
		wrRef = new WardrobeObjRef();
		wrRef.anim = GetComponent<Animator>();

		wrRef.anim = GetComponent<Animator>();
		wrRef.outfitTrans = base.transform.Find("Outfits");
		wrRef.playerImageTrans = base.transform.Find("PlayerImage");
		wrRef.playerImages = new Image[wrRef.playerImageTrans.childCount];
		int num = 0;
		foreach (Transform playerImageTran in wrRef.playerImageTrans)
		{
			wrRef.playerImages[num] = playerImageTran.GetComponent<Image>();
			wrRef.playerImages[num].material = new Material(wrRef.playerImages[num].material);
			wrRef.playerImages[num].material.SetColor("_OutlineColor", curOutfitOutlineColor);
			num++;
		}
		wrRef.outfitImageArray = new Image[totalOutfitCount];
		wrRef.outfitBGImageArray = new Image[totalOutfitCount];
		wrRef.outfitSelImageArray = new Image[totalOutfitCount];
		wrRef.outfitAnimArray = new Animator[totalOutfitCount];
		wrRef.outfitLockedImageArray = new Image[totalOutfitCount];
		currentAngle = (float)Math.PI / 2f;
		for (int i = 0; i < totalOutfitCount; i++)
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(ChaosBundle.Get("Assets/Prefabs/UI/WardrobeUIOutfit.prefab"));
			gameObject.transform.SetParent(wrRef.outfitTrans);
			RectTransform component = gameObject.GetComponent<RectTransform>();
			component.anchoredPosition = 58f * new Vector2(Mathf.Cos(currentAngle), Mathf.Sin(currentAngle));
			currentAngle -= angleIncrement;
			component.localScale = Vector3.one;
			wrRef.outfitBGImageArray[i] = gameObject.transform.Find("OutfitBG").GetComponent<Image>();
			wrRef.outfitSelImageArray[i] = gameObject.transform.Find("OutfitSelectEffect").GetComponent<Image>();
			wrRef.outfitAnimArray[i] = gameObject.GetComponent<Animator>();
			wrRef.outfitImageArray[i] = gameObject.transform.Find("Outfit").GetComponent<Image>();
			wrRef.outfitImageArray[i].material = new Material(wrRef.outfitImageArray[i].material);
			wrRef.outfitSelImageArray[i].material = new Material(wrRef.outfitImageArray[i].material);
			wrRef.outfitLockedImageArray[i] = gameObject.transform.Find("OutfitBGLocked").GetComponent<Image>();
		}
		targetAngle = currentAngle;
		rotationOrientation = 0;
		wrRef.infoTitleText = transform.Find("InfoBox/TitleText").GetComponent<Text>();
		wrRef.infoDescText = transform.Find("InfoBox/MainText").GetComponent<Text>();
		TextManager.AddUIRef(string.Empty, wrRef.infoTitleText);
		TextManager.AddUIRef(string.Empty, wrRef.infoDescText);
	}

	private void UpdateOutfits(int givenIndex)
	{
		bool unlocked = availableOutfitList[givenIndex].unlocked;
		if (unlocked)
		{
			Image[] playerImages = wrRef.playerImages;
			int excludeIndex = currentPlayerImageIndex;
			currentPlayerImageIndex = playerImages.GetRandomIndex(0, excludeIndex);
			wrRef.playerImages[currentPlayerImageIndex].material.SetFloat("_PaletteIndex", availableOutfitList[givenIndex].outfitColorIndex);
		}
		for (int i = 0; i < wrRef.playerImages.Length; i++)
		{
			wrRef.playerImages[i].gameObject.SetActive(unlocked && i == currentPlayerImageIndex);
		}
		wrRef.playerImageTrans.localScale = new Vector3(((!(UnityEngine.Random.value > 0.5f)) ? 1f : (-1f)) * wrRef.playerImageTrans.localScale.x, 1f * wrRef.playerImageTrans.localScale.y, 1f * wrRef.playerImageTrans.localScale.z);
		LoadInfo(availableOutfitList[givenIndex]);
	}

	private void HandleOutfitOutlines(int currentOutfitIndex)
	{
		for (int i = 0; i < wrRef.outfitImageArray.Length; i++)
		{
			wrRef.outfitImageArray[i].material.SetColor("_OutlineColor", (currentOutfitIndex != i) ? outfitOutlineColor : curOutfitOutlineColor);
		}
	}

	private void HandleSelectionRotation(float givenAngle, int givenIndex)
	{
		wrRef.outfitTrans.rotation = Globals.GetRotationQuaternion(new Vector2(Mathf.Cos(givenAngle), Mathf.Sin(givenAngle)));
		for (int i = 0; i < wrRef.outfitImageArray.Length; i++)
		{
			wrRef.outfitImageArray[i].transform.localEulerAngles = Globals.GetRotationVector(new Vector2(0f - Mathf.Cos(givenAngle), Mathf.Sin(givenAngle)));
			wrRef.outfitSelImageArray[i].transform.localEulerAngles = Globals.GetRotationVector(new Vector2(0f - Mathf.Cos(givenAngle), Mathf.Sin(givenAngle)));
			wrRef.outfitBGImageArray[i].transform.localEulerAngles = -wrRef.outfitTrans.localEulerAngles;
			wrRef.outfitLockedImageArray[i].transform.localEulerAngles = -wrRef.outfitTrans.localEulerAngles;
			wrRef.outfitSelImageArray[i].transform.parent.localScale = ((i != givenIndex) ? (Vector3.one * 0.75f) : Vector3.one);
		}
	}

	private void LoadInfo(Outfit givenOutfit)
	{
		if (givenOutfit.unlocked)
		{
			wrRef.infoTitleText.text = TextManager.GetOutfitName(givenOutfit.outfitID);
			wrRef.infoDescText.text = ((!(givenOutfit.outfitID != Outfit.normalID)) ? "????" : givenOutfit.GetDescription());
		}
		else
		{
			wrRef.infoTitleText.text = TextManager.GetUIText("wardrobeUI-outfitLockedTitle");
			wrRef.infoDescText.text = TextManager.GetUIText("wardrobeUI-outfitLockedText");
		}
	}

	public void Activate(Player givenPlayer, Vector2 givenPosition)
	{
		if (!(givenPlayer == null))
		{
			gameObject.SetActive(value: true);
			player = givenPlayer;
			inputDev = player.inputDevice;
			LoadOutfits();
			isActive = true;
			activationPosition = givenPosition;
		}
	}

	public void Deactivate()
	{
		if (player != null)
		{
			player.fsm.ChangeState(player.fsm.defaultStateName);
		}
		player = null;
		inputDev = null;
		isActive = false;
		gameObject.SetActive(value: false);
	}

	private void Update()
	{
		if (targetAngle != currentAngle)
		{
			currentAngle += Time.deltaTime * rotationSpeed * (float)rotationOrientation;
			switch (rotationOrientation)
			{
			case -1:
				if (currentAngle < targetAngle)
				{
					currentAngle = targetAngle;
					rotationOrientation = 0;
					UpdateOutfits(currentOutfitIndex);
				}
				break;
			case 1:
				if (currentAngle > targetAngle)
				{
					currentAngle = targetAngle;
					rotationOrientation = 0;
					UpdateOutfits(currentOutfitIndex);
				}
				break;
			}
			HandleSelectionRotation(currentAngle, currentOutfitIndex);
			HandleOutfitOutlines(currentOutfitIndex);
		}
		else
		{
			if (!isActive || GameUI.pauseMenu.paused)
			{
				return;
			}
			if (player == null || Vector2.Distance(player.transform.position, activationPosition) > maxDistance)
			{
				Deactivate();
				return;
			}
			HandleOutfitSelection();
			if (inputDev.GetButtonDown("Confirm"))
			{
				AssignOutfit(availableOutfitList[currentOutfitIndex], currentOutfitIndex);
			}
			else if (inputDev.GetButtonUp("Cancel"))
			{
				Deactivate();
			}
		}
	}

	private void AssignOutfit(Outfit givenOutfit, int givenIndex)
	{
		if (!Outfit.OutfitIsInUse(givenOutfit.outfitID, player.playerID) && player.EquipOutfit(givenOutfit.outfitID))
		{
			SoundManager.PlayAudio("Equip");
			wrRef.outfitAnimArray[givenIndex].Play("Select", -1, 0f);
			GameDataManager.Save(updateCurrentData: true, updatePlayerData: true);
		}
		else
		{
			SoundManager.PlayAudio("MenuError");
		}
	}

	private void HandleOutfitSelection()
	{
		currentOutfitIndex = GetNavigationIndex(currentOutfitIndex, GetInputDirection(inputDev.GetMoveVector()));
	}

	private int GetNavigationIndex(int givenIndex, InputDirection givenInputDir)
	{
		if (givenInputDir == InputDirection.None)
		{
			initNavDelayReset = true;
			navTimer.IsRunning = false;
			autoNavTimer.IsRunning = false;
			return givenIndex;
		}
		if (navTimer.IsRunning || autoNavTimer.IsRunning)
		{
			return givenIndex;
		}
		int num = givenIndex;
		switch (givenInputDir)
		{
		case InputDirection.Left:
			targetAngle -= angleIncrement;
			rotationOrientation = -1;
			num--;
			if (num < 0)
			{
				num = totalOutfitCount - 1;
			}
			break;
		case InputDirection.Right:
			targetAngle += angleIncrement;
			rotationOrientation = 1;
			num++;
			if (num >= totalOutfitCount)
			{
				num = 0;
			}
			break;
		}
		if (num != givenIndex)
		{
			SoundManager.PlayAudio("MenuMove");
			if (initNavDelayReset)
			{
				initNavDelayReset = false;
				navTimer.IsRunning = true;
			}
			else
			{
				autoNavTimer.IsRunning = true;
			}
		}
		return num;
	}

	private InputDirection GetInputDirection(Vector2 givenInputVec)
	{
		if (givenInputVec.x > 0.35f)
		{
			return InputDirection.Right;
		}
		if (givenInputVec.x < -0.35f)
		{
			return InputDirection.Left;
		}
		return InputDirection.None;
	}
