using System.Collections;
using UnityEngine;

public class CastBar : MiniUIBar
{
	private static GameObject prefab;

	private static Color defaultCastColor = new Color(0f, 0.6f, 1f, 0.8f);

	private static Color defaultFinishColor = Color.green;

	private Canvas canvas;

	private bool stillCasting;

	private bool forceQuitCasting;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/UI/CastBar.prefab"));

	public override void Awake()
	{
		base.Awake();
		uiBarImage.enabled = false;
		canvas = GetComponent<Canvas>();
	}

	public void StartCast(int givenSWID, bool givenStatus)
	{
		if (!GameController.hideUI && gameObject.activeSelf)
		{
			forceQuitCasting = false;
			stillCasting = true;
			StartCoroutine(CastBarStart(givenSWID, givenStatus));
		}
	}

	public void EndCast()
	{
		forceQuitCasting = false;
		stillCasting = false;
		uiBarImage.enabled = false;
		canvas.enabled = false;
	}

	public void ForceQuitCasting()
	{
		if (stillCasting)
		{
			forceQuitCasting = true;
		}
	}

	private void OnDisable()
	{
		EndCast();
	}

	private IEnumerator CastBarStart(int givenSWID, bool givenStatus)
	{
		canvas.enabled = true;
		uiBarImage.enabled = true;
		uiBarImage.color = defaultCastColor;
		float timePercentage = 0f;
		bool finishedCasting = false;
		while (stillCasting)
		{
			if (!finishedCasting)
			{
				timePercentage = ChaosStopwatch.GetTimePercentage(givenSWID);
				SetFillValue((!givenStatus) ? (1f - timePercentage) : timePercentage);
				if (timePercentage >= 1f)
				{
					finishedCasting = true;
					if (!givenStatus)
					{
						EndCast();
						yield break;
					}
					uiBarImage.color = defaultFinishColor;
				}
			}
			if (forceQuitCasting)
			{
				forceQuitCasting = false;
				yield break;
			}
			yield return null;
		}
		EndCast();
	}
}
