	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/UI/EnemyHealthBar.prefab"));

	private Graphic[] AllGraphics
	{
		get
		{
			if (_allGraphics == null)
			{
				_allGraphics = GetComponentsInChildren<Graphic>();
			}
			return _allGraphics;
		}
	}

	private void Awake()
	{
		enemyNameText = transform.Find("EnemyName").GetComponent<Text>();
		TextManager.AddUIRef(string.Empty, enemyNameText);
		HPBarFill = transform.Find("HealthBarFill").GetComponent<Image>();
		HPBarHurtFill = transform.Find("HealthBarHurtFill").GetComponent<Image>();
		shieldBarFill = transform.Find("ShieldBarFill").GetComponent<Image>();
	}

	private void Update()
	{
		if (enemy == null || enemy.health == null)
		{
			Release();
			return;
		}
		HandleHealth();
		HandleShield();
		HandleFillIn();
	}

	private void Release()
	{
		Reset();
		gameObject.SetActive(value: false);
	}

	private void Reset()
	{
		enemy = null;
		isHealthChanging = false;
		changingHealth = 0f;
		currentHealth = 0f;
		prevHealth = 0f;
		HPBarFill.fillAmount = 0f;
		HPBarHurtFill.fillAmount = 0f;
		shieldBarFill.fillAmount = 0f;
		fillingIn = false;
		fadeInTime = 0.5f;
		fillInTime = 1f;
		fillInTimer = fillInTime;
	}

	public void Claim(Enemy enemy)
	{
		Reset();
		this.enemy = enemy;
		gameObject.SetActive(value: true);
	}

	public void FadeIn()
	{
		if (!gameObject.activeSelf)
		{
			gameObject.SetActive(value: true);
		}
		Graphic[] allGraphics = AllGraphics;
		foreach (Graphic graphic in allGraphics)
		{
			graphic.canvasRenderer.SetAlpha(0.01f);
			graphic.enabled = true;
			graphic.CrossFadeAlpha(1f, 0.25f, ignoreTimeScale: false);
		}
		fillingIn = true;
	}

	private void HandleFillIn()
	{
		if (fillingIn)
		{
			if (fillInTimer <= 0f)
			{
				fillingIn = false;
				return;
			}
			fillInTimer -= Time.deltaTime;
			fillAmount = 1f - fillInTimer / fillInTime;
			HPBarFill.fillAmount = fillAmount;
			HPBarHurtFill.fillAmount = fillAmount;
		}
	}

	private void HandleHealth()
	{
		currentHealth = enemy.health.healthStat.CurrentValue;
		if (currentHealth < prevHealth)
		{
			if (ChaosStopwatch.Check(healthDelayStopwatchID))
			{
				changingHealth = prevHealth;
			}
			healthDelayStopwatchID = ChaosStopwatch.Begin(healthUpdateDelayTime);
		}
		changingHealth -= ((!(changingHealth > currentHealth)) ? 0f : (Time.deltaTime * hurtFillSpeed));
		prevHealth = currentHealth;
		HPBarFill.fillAmount = enemy.health.HealthPercentage;
		HPBarHurtFill.fillAmount = changingHealth / enemy.health.healthStat.ModifiedValue;
	}

	private void HandleShield()
	{
		shieldBarFill.fillAmount = enemy.health.ShieldPercentage;
	}

	public void SetName(string givenName)
	{
		enemyNameText.text = givenName;
	}
