	public static List<CompassIndicatorType> miscTypeList = new List<CompassIndicatorType>
	{
		CompassIndicatorType.CursedStore,
		CompassIndicatorType.PinataRoom,
		CompassIndicatorType.NurseRoom,
		CompassIndicatorType.SlotsRoom,
		CompassIndicatorType.TailorRoom,
		CompassIndicatorType.CollectorRoom,
		CompassIndicatorType.BankerRoom
	};

	public CompassIndicator[] compassIndicators;

	private Dictionary<CompassIndicatorType, int> compassIndicatorDict;

	public static Compass Instance => instance;

	private void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		Object.DontDestroyOnLoad(gameObject);
		compassIndicatorDict = new Dictionary<CompassIndicatorType, int>();
		for (int i = 0; i < compassIndicators.Length; i++)
		{
			compassIndicatorDict[compassIndicators[i].indicatorID] = i;
		}
	}

	public void Activate(CompassIndicatorType indicatorID, Vector3 targetPosition = default(Vector3), Transform targetTransform = null, bool revealedByMap = false)
	{
		if (!Level.isBossRushMode)
		{
			compassIndicators[compassIndicatorDict[indicatorID]].Activate(targetPosition, targetTransform, revealedByMap);
		}
	}

	public void Deactivate(CompassIndicatorType indicatorID)
	{
		compassIndicators[compassIndicatorDict[indicatorID]].Deactivate();
	}

	private void OnLevelWasLoaded()
	{
		for (int i = 0; i < compassIndicators.Length; i++)
		{
			compassIndicators[i].Deactivate();
		}
	}

	private void LateUpdate()
	{
		transform.position = new Vector3(GameController.cameraController.transform.position.x, GameController.cameraController.transform.position.y, transform.position.z);
		for (int i = 0; i < compassIndicators.Length; i++)
		{
			CompassIndicator compassIndicator = compassIndicators[i];
			if (compassIndicator.active && 0 == 0)
			{
				Vector3 vector = compassIndicator.targetPosition;
				if (compassIndicator.targetTransform != null)
				{
					vector = compassIndicator.targetTransform.position;
				}
				float num = Vector2.Distance(transform.position, vector);
				if (num <= compassIndicator.pointerHideDist)
				{
					compassIndicator.spriteRenderer.enabled = false;
					continue;
				}
				compassIndicator.spriteRenderer.enabled = true;
				Vector2 vector2 = ((Vector2)transform.position - (Vector2)vector).normalized * Mathf.Lerp(compassIndicator.minPointerDist, compassIndicator.maxPointerDist, Mathf.Clamp(num / compassIndicator.maxPointerDist * 0.75f, 0f, 1f));
				vector2 = -vector2;
				compassIndicator.spriteTransform.localPosition = new Vector3(vector2.x, vector2.y, 0f);
				float num2 = Globals.Vector2AngleWithPivot((Vector2)compassIndicator.spriteTransform.position + Vector2.up, compassIndicator.spriteTransform.position, vector);
				compassIndicator.spriteTransform.localEulerAngles = new Vector3(compassIndicator.spriteTransform.localEulerAngles.x, compassIndicator.spriteTransform.localEulerAngles.y, 0f - num2);
			}
		}
	}
}
