		revealCol = GetComponent<BoxCollider2D>();
		minimapIconDict = new Dictionary<Compass.CompassIndicatorType, int>();
		for (int i = 0; i < minimapIcons.Length; i++)
		{
			minimapIconDict[minimapIcons[i].indicatorType] = i;
		}
	}

	private void OnTriggerEnter2D(Collider2D col)
	{
		if (col.gameObject.name == "AllyMinimapRevealer")
		{
			Activate();
		}
	}

	public void SetIconOverride(Sprite newIcon = null)
	{
		iconOverride = newIcon;
		iconRenderer.sprite = ((!(newIcon == null)) ? newIcon : minimapIcons[minimapIconDict[indicatorType]].minimapSprite);
		iconRenderer.enabled = false;
	}

	public void Activate(bool revealedByStageMapVal = false)
	{
		if (!(iconRenderer == null) && !(revealCol == null) && minimapIconDict != null)
		{
			iconRenderer.sprite = ((!(iconOverride == null)) ? iconOverride : minimapIcons[minimapIconDict[indicatorType]].minimapSprite);
			iconRenderer.enabled = true;
			revealed = true;
			revealedByStageMap = revealedByStageMapVal;
			if (!revealedByStageMap && revealCol != null)
			{
				revealCol.enabled = false;
			}
			if (!compassIgnoreArray.Contains(indicatorType))
			{
				Compass compass = GameController.compass;
				Compass.CompassIndicatorType indicatorID = indicatorType;
				Vector3 position = transform.position;
				bool revealedByMap = revealedByStageMapVal;
				compass.Activate(indicatorID, position, null, revealedByMap);
			}
		}
	}

	public void Deactivate()
	{
		if (iconRenderer != null)
		{
			iconRenderer.enabled = false;
		}
		if (revealCol != null)
		{
			revealCol.enabled = true;
		}
		revealed = false;
		revealedByStageMap = false;
		if (!compassIgnoreArray.Contains(indicatorType))
		{
			GameController.compass.Deactivate(indicatorType);
		}
	}

	public static CompassIndicatorTrigger Spawn(Compass.CompassIndicatorType indicatorType, Vector3 position, Transform parentTrans = null, float scaleOverride = 1f, float colliderScale = -1f)
	{
		GameObject gameObject = Object.Instantiate(CompassIndicatorTriggerPrefab);
		CompassIndicatorTrigger component = gameObject.GetComponent<CompassIndicatorTrigger>();
		if (parentTrans != null)
		{
			gameObject.transform.SetParent(parentTrans);
		}
		gameObject.transform.position = new Vector3(position.x, position.y, cameraZPos);
		component.indicatorType = indicatorType;
		gameObject.gameObject.name = "CompassIndicatorTrigger (" + component.indicatorType.ToString() + ")";
		if (scaleOverride != 1f)
		{
			component.iconRenderer.transform.localScale = new Vector3(scaleOverride, scaleOverride, 1f);
		}
		if (colliderScale != -1f)
		{
			component.revealCol.transform.localScale = new Vector3(colliderScale, colliderScale, 1f);
		}
		Triggers.RemoveAll((CompassIndicatorTrigger t) => t == null);
		Triggers.Add(component);
		Level.ctDict[indicatorType] = component;
		if (Compass.miscTypeList.Contains(indicatorType))
		{
			Level.miscType = indicatorType;
		}
		return component;
	}
