using UnityEngine;
using UnityEngine.UI;

public class MainWindow : MonoBehaviour
{
	public enum Window
	{
		Element,
		Skill,
		Options,
		Info,
		Equip,
		None
	}

	public enum Option
	{
		Buy,
		Equip,
		Ultimate,
		Info
	}

	public bool backButtonWasClicked;

	public Window focusWindow;

	private Window prevFocusWindow;

	private Window queuedFocusWindow;

	private bool focusQueued;

	public Player currentPlayer;

	private CurrentGoldUI currentGold;

	private ElementSelectionUI elementSelection;

	private SkillSelectionUI skillSelection;

	private OptionsWindowUI optionsWindow;

	private SkillInfoWindowUI skillInfo;

	private EquipWindowUI equipWindow;

	private Image backButtonImage;

	private Text backButtonText;

	private bool inputDevFound;

	private void OnEnable()
	{
		focusWindow = Window.None;
		QueueFocusChange(Window.Element);
		inputDevFound = false;
	}

	private void OnDisable()
	{
		if (skillSelection != null)
		{
			skillSelection.gameObject.SetActive(value: false);
		}
		if (skillInfo != null)
		{
			skillInfo.gameObject.SetActive(value: false);
		}
	}

	private void Start()
	{
		currentGold = transform.Find("CurrentGold").GetComponent<CurrentGoldUI>();
		elementSelection = transform.Find("ElementSelection").GetComponent<ElementSelectionUI>();
		skillSelection = transform.Find("SkillSelection").GetComponent<SkillSelectionUI>();
		skillSelection.gameObject.SetActive(value: false);
		optionsWindow = transform.Find("MenuOptionsWindow").GetComponent<OptionsWindowUI>();
		optionsWindow.gameObject.SetActive(value: false);
		skillInfo = transform.Find("SkillInfoWindow").GetComponent<SkillInfoWindowUI>();
		skillInfo.gameObject.SetActive(value: false);
		equipWindow = transform.Find("EquipWindow").GetComponent<EquipWindowUI>();
		equipWindow.gameObject.SetActive(value: false);
		backButtonImage = transform.Find("BackButton/BackIcon/Image").GetComponent<Image>();
	}

	private void Update()
	{
		if (!inputDevFound)
		{
			SetUIButtonsToMatchInputDev();
			inputDevFound = true;
		}
		currentGold.currentPlayer = currentPlayer;
		HandleFocusChange();
		switch (focusWindow)
		{
		case Window.Element:
			if (prevFocusWindow != Window.Element)
			{
				elementSelection.currentPlayer = currentPlayer;
				elementSelection.LoadElements();
			}
			if ((currentPlayer.inputDevice.GetButton("Confirm") || (elementSelection.elementClicked && currentPlayer.IsKeyboardInput)) && elementSelection.selectedElement != null)
			{
				QueueFocusChange(Window.Skill);
			}
			if (currentPlayer.inputDevice.GetButtonUp("Cancel") || (backButtonWasClicked && currentPlayer.IsKeyboardInput))
			{
				currentPlayer.fsm.ChangeState(currentPlayer.fsm.defaultStateName);
				gameObject.SetActive(value: false);
			}
			break;
		case Window.Skill:
			if (prevFocusWindow != Window.Skill)
			{
				skillSelection.currentPlayer = currentPlayer;
				skillSelection.elementType = elementSelection.selectedElement.name;
				skillSelection.elementSprite = elementSelection.elementSprites[skillSelection.elementType];
				if (prevFocusWindow == Window.Element)
				{
					skillSelection.LoadSkills();
				}
				else
				{
					skillSelection.LoadSkills(updateOnly: true);
				}
			}
			if (currentPlayer.inputDevice.GetButtonUp("Cancel") || (backButtonWasClicked && currentPlayer.IsKeyboardInput))
			{
				QueueFocusChange(Window.Element);
			}
			if (currentPlayer.inputDevice.GetButtonDown("Confirm") || (skillSelection.skillClicked && currentPlayer.IsKeyboardInput))
			{
				QueueFocusChange(Window.Options);
			}
			break;
		case Window.Options:
			if (prevFocusWindow != Window.Options)
			{
				optionsWindow.currentPlayer = currentPlayer;
				if (prevFocusWindow == Window.Info || prevFocusWindow == Window.Equip)
				{
					optionsWindow.LoadMenu(skillSelection.selectedSkill, updating: true);
				}
				else
				{
					optionsWindow.LoadMenu(skillSelection.selectedSkill);
				}
			}
			if (currentPlayer.inputDevice.GetButtonUp("Cancel") || (backButtonWasClicked && currentPlayer.IsKeyboardInput))
			{
				QueueFocusChange(Window.Skill);
			}
			if (!currentPlayer.inputDevice.GetButtonDown("Confirm") && (!optionsWindow.optionWasClicked || !currentPlayer.IsKeyboardInput))
			{
				break;
			}
			optionsWindow.optionWasClicked = false;
			switch (optionsWindow.selectedOption)
			{
			case Option.Buy:
				if (optionsWindow.BuySkill(skillSelection.selectedSkill))
				{
					QueueFocusChange(Window.Skill);
				}
				break;
			case Option.Equip:
				if (skillSelection.selectedSkill.currentLevel > 0)
				{
					QueueFocusChange(Window.Equip);
				}
				else
				{
					SoundManager.PlayAudio("MenuError");
				}
				break;
			case Option.Ultimate:
				equipWindow.currentPlayer = currentPlayer;
				if (equipWindow.DesignateUltimate(skillSelection.selectedSkill))
				{
					QueueFocusChange(Window.Skill);
					break;
				}
				equipWindow.equipAsUlt = true;
				QueueFocusChange(Window.Equip);
				break;
			case Option.Info:
				QueueFocusChange(Window.Info);
				break;
			}
			optionsWindow.LoadMenu(skillSelection.selectedSkill, updating: true);
			if (queuedFocusWindow != Window.Options)
			{
				optionsWindow.MakeSelectionTransparent();
			}
			break;
		case Window.Info:
			if (prevFocusWindow != Window.Info)
			{
				skillInfo.LoadInfo(skillSelection.selectedSkill);
			}
			if (currentPlayer.inputDevice.GetButtonUp("Cancel") || (backButtonWasClicked && currentPlayer.IsKeyboardInput))
			{
				QueueFocusChange(Window.Options);
			}
			break;
		case Window.Equip:
			if (prevFocusWindow != Window.Equip)
			{
				equipWindow.currentPlayer = currentPlayer;
				equipWindow.LoadEquipWindow(skillSelection.selectedSkill);
			}
			if (equipWindow.equippingFinished || (backButtonWasClicked && currentPlayer.IsKeyboardInput))
			{
				QueueFocusChange(Window.Skill);
			}
			break;
		}
	}

	private void QueueFocusChange(Window nextFocus)
	{
		focusQueued = true;
		queuedFocusWindow = nextFocus;
		SoundManager.PlayAudio("MenuMove");
	}

	private void HandleFocusChange()
	{
		prevFocusWindow = focusWindow;
		if (focusQueued)
		{
			focusWindow = queuedFocusWindow;
			focusQueued = false;
			switch (focusWindow)
			{
			case Window.Element:
				elementSelection.hasFocus = true;
				skillSelection.gameObject.SetActive(value: false);
				optionsWindow.gameObject.SetActive(value: false);
				skillInfo.gameObject.SetActive(value: false);
				equipWindow.gameObject.SetActive(value: false);
				break;
			case Window.Skill:
				elementSelection.hasFocus = false;
				skillSelection.hasFocus = true;
				skillSelection.gameObject.SetActive(value: true);
				optionsWindow.gameObject.SetActive(value: false);
				skillInfo.gameObject.SetActive(value: false);
				equipWindow.gameObject.SetActive(value: false);
				break;
			case Window.Options:
				elementSelection.hasFocus = false;
				skillSelection.hasFocus = false;
				optionsWindow.hasFocus = true;
				optionsWindow.gameObject.SetActive(value: true);
				skillInfo.gameObject.SetActive(value: false);
				equipWindow.gameObject.SetActive(value: false);
				break;
			case Window.Info:
				elementSelection.hasFocus = false;
				skillSelection.hasFocus = false;
				optionsWindow.hasFocus = false;
				skillInfo.hasFocus = true;
				skillInfo.gameObject.SetActive(value: true);
				break;
			case Window.Equip:
				elementSelection.hasFocus = false;
				skillSelection.hasFocus = false;
				optionsWindow.hasFocus = false;
				equipWindow.gameObject.SetActive(value: true);
				break;
			}
			backButtonWasClicked = false;
		}
	}

	public void BackButtonClick()
	{
		backButtonWasClicked = true;
	}

	private void SetUIButtonsToMatchInputDev()
	{
		if (currentPlayer.IsKeyboardInput)
		{
			backButtonImage.sprite = GameUI.KeyboardKeyIcons["Escape"];
		}
		else
		{
			backButtonImage.sprite = GameUI.UIButtonIcons["GamepadButtonRed"];
		}
	}
}

