using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class OptionsWindowUI : MonoBehaviour
{
	public Player currentPlayer;

	public bool hasFocus;

	public MainWindow.Option selectedOption;

	public bool optionWasClicked;

	private Image skillIcon;

	private Text skillName;

	private bool isMaxed;

	private bool isUltimate;

	private List<Image> optionsList;

	private List<Text> optionsListText;

	private Color maxedColor;

	private Color transparentColor;

	private bool inputReceived;

	private Vector2 cursorVector;

	private int currentIndex;

	private int prevIndex;

	private int originalIndex;

	private int optionsCount;

	private bool objectsSet;

	private void Start()
	{
		skillIcon = transform.Find("Title/SkillIcon").GetComponent<Image>();
		skillName = transform.Find("Title/SkillName").GetComponent<Text>();
		optionsList = new List<Image>();
		optionsList.Add(transform.Find("BuyOption").GetComponent<Image>());
		optionsList.Add(transform.Find("EquipOption").GetComponent<Image>());
		optionsList.Add(transform.Find("InfoOption").GetComponent<Image>());
		optionsList.Add(transform.Find("UltimateOption").GetComponent<Image>());
		optionsListText = new List<Text>();
		optionsListText.Add(transform.Find("BuyOption/Text").GetComponent<Text>());
		optionsListText.Add(transform.Find("EquipOption/Text").GetComponent<Text>());
		optionsListText.Add(transform.Find("InfoOption/Text").GetComponent<Text>());
		optionsListText.Add(transform.Find("UltimateOption/Text").GetComponent<Text>());
		transparentColor = Color.white;
		transparentColor.a = 0f;
		maxedColor = new Color(1f, 0.725f, 0f, 1f);
		objectsSet = true;
	}

	public void LoadMenu(Player.SkillState selectedSkill, bool updating = false)
	{
		if (!objectsSet)
		{
			Start();
		}
		skillIcon.sprite = IconManager.GetSkillIcon(selectedSkill.skillID);
		skillName.text = TextManager.GetSkillName(selectedSkill.skillID);
		isUltimate = selectedSkill.isUltimate;
		foreach (Image options in optionsList)
		{
			options.color = transparentColor;
		}
		foreach (Text item in optionsListText)
		{
			item.color = Color.white;
		}
		optionsListText[0].text = "Buy";
		optionsList[3].gameObject.SetActive(value: false);
		optionsCount = 3;
		isMaxed = false;
		if (selectedSkill.currentLevel == SkillStats.maxSkillLevel)
		{
			isMaxed = true;
			optionsListText[0].text = "MAX";
			optionsListText[0].color = maxedColor;
			optionsList[3].gameObject.SetActive(value: true);
			if (selectedSkill.isUltimate)
			{
				optionsListText[3].color = maxedColor;
			}
			else
			{
				optionsListText[3].color = Color.white;
			}
			optionsCount = 4;
		}
		else if (selectedSkill.skillData.GetValue<int>("goldCost", selectedSkill.currentLevel + 1) > Player.goldWallet.balance)
		{
			optionsListText[0].color = Color.gray;
		}
		if (selectedSkill.currentLevel == 0)
		{
			optionsListText[1].color = Color.gray;
		}
		if (!updating)
		{
			currentIndex = 0;
		}
		SelectOption(currentIndex);
		optionWasClicked = false;
	}

	private void Update()
	{
		if (hasFocus)
		{
			HandleNavigation();
		}
	}

	private void HandleNavigation()
	{
		originalIndex = currentIndex;
		if (optionsListText[currentIndex].color == Color.gray)
		{
			currentIndex = ChangeIndex(currentIndex, add: true);
			SelectOption(currentIndex);
		}
		cursorVector = currentPlayer.inputDevice.GetMoveVector();
		if (inputReceived && Mathf.Abs(cursorVector.y) < 0.2f)
		{
			inputReceived = false;
		}
		else
		{
			if (inputReceived || !(Mathf.Abs(cursorVector.y) > 0.3f))
			{
				return;
			}
			inputReceived = true;
			prevIndex = currentIndex;
			if (cursorVector.y > 0f)
			{
				originalIndex = currentIndex;
				currentIndex = ChangeIndex(currentIndex, add: false);
				while (currentIndex != originalIndex && optionsListText[currentIndex].color == Color.gray)
				{
					currentIndex = ChangeIndex(currentIndex, add: false);
				}
			}
			else
			{
				originalIndex = currentIndex;
				currentIndex = ChangeIndex(currentIndex, add: true);
				while (currentIndex != originalIndex && optionsListText[currentIndex].color == Color.gray)
				{
					currentIndex = ChangeIndex(currentIndex, add: true);
				}
			}
			SelectOption(currentIndex);
			if (currentIndex != originalIndex)
			{
				SoundManager.PlayAudio("MenuMove");
			}
		}
	}

	private int ChangeIndex(int index, bool add)
	{
		int num = index;
		num = ((!add) ? (num - 1) : (num + 1));
		if (num < 0)
		{
			num = optionsCount - 1;
		}
		else if (num >= optionsCount)
		{
			num = 0;
		}
		return num;
	}

	public void SelectOption(int index)
	{
		if (optionsListText[prevIndex].color != Color.gray)
		{
			optionsListText[prevIndex].color = Color.white;
		}
		if (prevIndex == 0 && isMaxed)
		{
			optionsListText[prevIndex].color = maxedColor;
		}
		else if (prevIndex == 3 && isUltimate)
		{
			optionsListText[prevIndex].color = maxedColor;
		}
		prevIndex = index;
		if (optionsListText[index].color != Color.gray)
		{
			optionsListText[index].color = Color.green;
		}
		currentIndex = index;
		switch (index)
		{
		case 0:
			selectedOption = MainWindow.Option.Buy;
			break;
		case 1:
			selectedOption = MainWindow.Option.Equip;
			break;
		case 2:
			selectedOption = MainWindow.Option.Info;
			break;
		case 3:
			selectedOption = MainWindow.Option.Ultimate;
			break;
		}
	}

	public bool BuySkill(Player.SkillState selectedSkill)
	{
		int num = 0;
		if (selectedSkill.currentLevel == SkillStats.maxSkillLevel)
		{
			SoundManager.PlayAudio("MenuError");
			return false;
		}
		num = selectedSkill.skillData.GetValue<int>("goldCost", selectedSkill.currentLevel + 1);
		if (Player.goldWallet.Withdraw(num))
		{
			selectedSkill.SetSkillLevel(selectedSkill.currentLevel + 1);
			SoundManager.PlayAudio("MenuBuy");
			return true;
		}
		SoundManager.PlayAudio("MenuError");
		return false;
	}

	public void MakeSelectionTransparent()
	{
		optionsListText[currentIndex].color = Color.white;
	}

	public void OptionClicked(int selection)
	{
		prevIndex = currentIndex;
		currentIndex = selection;
		SelectOption(currentIndex);
		optionWasClicked = true;
	}
}
