using System.Collections;
using System.Collections.Generic;
using Steamworks;
using UnityEngine;
using UnityEngine.SceneManagement;

public class InitialLoad : MonoBehaviour
{
	private Animator anim;

	public static bool useSteamManager = true;

	private void Awake()
	{
		anim = GetComponent<Animator>();
	}

	private void Start()
	{
		ChaosBundle.LoadBundle();
		SoundManager.muteAudio = true;
		if (GameController.resetGameDataQueued)
		{
			GameController.resetGameDataQueued = false;
			GameDataManager.ResetAllData();
			if (Player.NewSpellManager != null)
			{
				Player.NewSpellManager.Reset();
			}
			if (Player.newItems != null)
			{
				foreach (List<string> value in Player.newItems.Values)
				{
					value?.Clear();
				}
			}
		}
		StartCoroutine(LoadTitleScreenAsync());
	}

	private IEnumerator LoadTitleScreenAsync()
	{
		if (useSteamManager)
		{
			yield return StartCoroutine(LoadSteam());
		}
		else
		{
			GameDataManager.LoadInitial(mainInit: true);
		}
		yield return Globals.waitForQuarter;
		Object.Instantiate(ChaosBundle.Get("Assets/Prefabs/MainCamera.prefab"));
		Object.Instantiate(ChaosBundle.Get("Assets/Prefabs/GameController.prefab"));
		if (useSteamManager)
		{
			AchievementManager.Initialize(GameController.Instance);
		}
		yield return Globals.waitForQuarter;
		AsyncOperation asyncOp = SceneManager.LoadSceneAsync("TitleScreen", LoadSceneMode.Additive);
		yield return asyncOp;
		while (!asyncOp.isDone)
		{
			yield return null;
		}
		SoundManager.muteAudio = false;
		anim.Play("FadeOut", -1, 0f);
		SoundManager.PlayBGM("TitleScreen");
		if (Input.GetKey(KeyCode.Escape))
		{
			GameDataManager.gameSettings.Reset();
		}
	}

	private IEnumerator LoadSteam()
	{
		Object.Instantiate(ChaosBundle.Get("Assets/Prefabs/SteamManager.prefab"));
		while (!SteamManager.Initialized)
		{
			yield return null;
		}
		GameDataManager.steamIDStr = SteamUser.GetSteamID().GetAccountID().m_AccountID + "/";
		GameDataManager.LoadInitial(mainInit: true);
	}
}
