private void Update()
{
	if (firstFrame)
	{
		firstFrame = false;
	}
	else if (inConfirmWindow)
	{
		if (exitConfirmWindow)
		{
			exitConfirmWindow = false;
			inConfirmWindow = false;
			navLocked = true;
		}
		else if (Input.GetKeyUp(KeyCode.Escape) || InputKeyRecorded(currentCInput))
		{
			exitConfirmWindow = true;
			cmRef.confirmationWindow.SetActive(value: false);
			RefreshFields();
		}
	}
	else
	{
		HandleNavigation();
		if (InputController.GetAnyDeviceButtonUp("Cancel") != null)
		{
			CancelSelected();
		}
		if (InputController.GetAnyDeviceButtonDown("Confirm") != null)
		{
			ConfirmSelected();
		}
	}
}
private void RefreshFields()
{
	cmRef.mouseAimFill.enabled = ChaosInputDevice.allowMouseAim;
	cmRef.mouseDashFill.enabled = ChaosInputDevice.allowMouseDash;
	foreach (KeyValuePair<CInput, Text> item in cmRef.fieldValueDict)
	{
		if (!(item.Value == null) && inputToHandleDict.ContainsKey(item.Key))
		{
			if (item.Key.ToString().Contains("Move"))
			{
				item.Value.text = InputMapHelper.GetActionElementName(InputToActionName[item.Key], useAxis: true, item.Key == CInput.MoveUp || item.Key == CInput.MoveRight);
			}
			else
			{
				item.Value.text = InputMapHelper.GetActionElementName(InputToActionName[item.Key]);
			}
		}
	}
}
private bool InputKeyRecorded(CInput givenInput)
{
	if (Input.anyKeyDown)
	{
		KeyCode[] array = KeyCodeValues;
		for (int i = 0; i < array.Length; i++)
		{
			KeyCode keyCode = array[i];
			if (keyCode != KeyCode.Escape && keyCode != KeyCode.Return && !keyCode.ToString().Contains("Joystick") && Input.GetKeyDown(keyCode))
			{
				AssignKeyToInput(givenInput, keyCode);
				SoundManager.PlayConfirmAudio();
				return true;
			}
		}
	}
	return false;
}
private void AssignKeyToInput(CInput givenInput, KeyCode givenKey)
{
	InputMapHelper.CreateElementMapForAll(InputToActionName[givenInput], givenKey, (givenInput == CInput.MoveDown || givenInput == CInput.MoveLeft) ? Pole.Negative : Pole.Positive);
}
private void RequestConfirm()
{
	inConfirmWindow = true;
	cmRef.confirmationWindow.SetActive(value: true);
}
private void ConfirmSelected()
{
	currentCInput = cmRef.inputList[currentIndex];
	switch (currentCInput)
	{
	case CInput.MouseAim:
		ChaosInputDevice.allowMouseAim = !ChaosInputDevice.allowMouseAim;
		if (!ChaosInputDevice.allowMouseAim)
		{
			ChaosInputDevice.allowMouseDash = false;
		}
		RefreshFields();
		SoundManager.PlayConfirmAudio();
		break;
	case CInput.MouseDash:
		ChaosInputDevice.allowMouseDash = !ChaosInputDevice.allowMouseDash;
		if (ChaosInputDevice.allowMouseDash)
		{
			ChaosInputDevice.allowMouseAim = true;
		}
		RefreshFields();
		SoundManager.PlayConfirmAudio();
		break;
	case CInput.Reset:
		GameDataManager.gameSettings.inputSettings.Reset();
		LoadMenu();
		RefreshFields();
		SoundManager.PlayConfirmAudio();
		break;
	case CInput.Back:
		ExitMenu();
		break;
	default:
		RequestConfirm();
		break;
	}
}
private void CancelSelected()
{
	ExitMenu();
}
private void HandleNavigation(int givenIndex = -1)
{
	if (givenIndex != -1 && givenIndex != currentIndex)
	{
		currentIndex = givenIndex;
	}
	else
	{
		switch (GetInputDirection())
		{
		case InputDirection.Up:
			if (!navLocked)
			{
				currentIndex--;
				if (currentIndex < 0)
				{
					currentIndex = cmRef.inputList.Count - 1;
				}
			}
			break;
		case InputDirection.Down:
			if (!navLocked)
			{
				currentIndex++;
				if (currentIndex >= cmRef.inputList.Count)
				{
					currentIndex = 0;
				}
			}
			break;
		default:
			navLocked = false;
			return;
		}
	}
	if (!navLocked)
	{
		SoundManager.PlayAudio("MenuMove", 1f, ignoreTimeRestriction: true);
	}
	HighlightOption(currentIndex);
	navLocked = true;
}
