	public void Display(string displayName, Sprite iconSprite = null, Sprite useKeySprite = null, bool isSkill = false, bool isSignature = false, bool isEmpowered = false, bool acquired = true)
	{
		if (!noticeQueue.Any((NoticeObject x) => x.objName == displayName))
		{
			noticeQueue.Enqueue(new NoticeObject(displayName, iconSprite, useKeySprite, isSkill, isSignature, acquired, isEmpowered));
		}
	}

	private void ShowDisplay(NoticeObject givenObj)
	{
		canvas.enabled = true;
		nameText.text = givenObj.objName;
		iconImage.gameObject.SetActive(givenObj.iconSprite != null);
		iconImage.sprite = givenObj.iconSprite;
		useKeyImage.gameObject.SetActive(givenObj.useKeySprite != null);
		useKeyImage.sprite = givenObj.useKeySprite;
		if (givenObj.isSkill)
		{
			skillBGImage.enabled = true;
			itemBGImage.enabled = false;
			if (givenObj.isSignature)
			{
				skillBGImage.sprite = arcanaFrontSigSprite;
			}
			else if (givenObj.isEmpowered)
			{
				skillBGImage.sprite = arcanaFrontEmpoweredSprite;
			}
			else
			{
				skillBGImage.sprite = arcanaFrontSprite;
			}
			if (givenObj.acquired)
			{
				anim.Play("SkillAcquired", -1, 0f);
			}
			else
			{
				anim.Play("SkillLost", -1, 0f);
				SoundManager.PlayAudio("LostArcana");
			}
		}
		else
		{
			skillBGImage.enabled = false;
			itemBGImage.enabled = true;
			if (givenObj.acquired)
			{
				anim.Play("ItemAquired", -1, 0f);
			}
			else
			{
				anim.Play("ItemLost", -1, 0f);
				SoundManager.PlayAudio("LostRelic");
			}
		}
		animPlaying = true;
	}

	private void LateUpdate()
	{
		if (parentTrans != null)
		{
			transform.position = new Vector3(parentTrans.position.x, parentTrans.position.y + yOffset, parentTrans.position.z);
		}
		if (anim.AnimPlayed(0.8f) && noticeQueue.Count > 0)
		{
			ShowDisplay(noticeQueue.Dequeue());
			return;
		}
		if (animPlaying && anim.AnimPlayed(0.4f))
		{
			animPlaying = false;
		}
		if (!canvas.enabled && anim.AnimPlayed() && noticeQueue.Count == 0)
		{
			canvas.enabled = false;
		}
	}
