private bool AssignPlayerSkill(SBFocus givenFocus)
{
	if (player == null || currentSkill == null)
	{
		return false;
	}
	int num = 0;
	switch (givenFocus)
	{
	case SBFocus.Player:
		num = sbRef.skillEquipSlots[playerInfoSelectedType];
		break;
	case SBFocus.Overdrive:
		num = 3;
		break;
	case SBFocus.Spell:
		if (player.GetSignatureSkill().skillID == currentSkill.skillID)
		{
			SoundManager.PlayAudio("MenuError");
			return false;
		}
		num = ((!currentSkill.isBasic) ? (currentSkill.isDash ? 1 : 2) : 0);
		break;
	}
	StartCoroutine(PlayArcanaEquipAnimation(currentSkill.skillID, num));
	if (num == 3)
	{
		Player.SkillState assignedSkill = player.GetAssignedSkill(currentSkill.skillID);
		Player.SkillState signatureSkill = player.GetSignatureSkill();
		if (assignedSkill == null)
		{
			signatureSkill.isSignature = false;
			signatureSkill.SetEmpowered(givenStatus: false, EmpowerStatMods.DefaultEmpowerMod);
			player.AssignSkillSlot(signatureSkill.SetSkillSlot(), currentSkill.skillID, setSignature: true, signatureStatus: true);
		}
		else if (!assignedSkill.isSignature)
		{
			player.AssignSkillSlot(signatureSkill.SetSkillSlot(), assignedSkill.skillID, setSignature: true, signatureStatus: true);
			player.AssignSkillSlot(assignedSkill.SetSkillSlot(), signatureSkill.skillID, setSignature: true);
		}
	}
	else
	{
		for (int i = 0; i < 6; i++)
		{
			if (player.assignedSkills[i] != null && !(player.assignedSkills[i].isBasic ^ currentSkill.isBasic) && !(player.assignedSkills[i].isDash ^ currentSkill.isDash) && !player.assignedSkills[i].isSignature)
			{
				player.AssignSkillSlot(i, currentSkill.skillID, setSignature: true);
				break;
			}
		}
	}
	player.lowerHUD.cooldownUI.RefreshEntries();
	SetEquipSlots(player);
	GameDataManager.Save(updateCurrentData: true, updatePlayerData: true);
	player.health.RestoreHealth(9999, showDisplayText: false, playSound: false, fullyRestoreHealth: true);
	return true;
}

