private void HandleSelectionColor()
{
	if ((fadeAlphaValue >= 1f && !fadeOut) || (fadeAlphaValue <= 0.6f && fadeOut))
	{
		fadeOut = !fadeOut;
	}
	fadeAlphaValue += Time.deltaTime * (float)((!fadeOut) ? 1 : (-1));
	selectionColor.a = fadeAlphaValue;
	selectionBorder.color = selectionColor;
	swapTextColor.a = fadeAlphaValue;
	swapText.color = swapTextColor;
	if (currentlySwapping)
	{
		skillToSwapColor.a = fadeAlphaValue;
		skillBorders[skillToSwapIndex].color = skillToSwapColor;
	}
}

private bool IsSignificantSkill(Player.SkillState skillToReplace, Player.SkillState incomingSkill = null)
{
	if (incomingSkill != null && incomingSkill.isBasic)
	{
		return skillToReplace == null || !skillToReplace.isBasic;
	}
	if ((skillToReplace == null || !skillToReplace.isBasic) && incomingSkill != null && incomingSkill.isBasic)
	{
		return true;
	}
	return skillToReplace != null && (skillToReplace.isSignature || skillToReplace.isBasic || skillToReplace.isDash);
}

private bool HandleQuickSwap()
{
	if (!quickSwapCompleted && player.inputDevice.GetButton("EquipMenu") && player.stockSkill != null)
	{
		skillBorders[6].color = Color.green;
		swapText.gameObject.SetActive(value: true);
		swapPrompt.SetActive(value: false);
		for (int i = 0; i < player.assignedSkills.Length; i++)
		{
			if (player.inputDevice.GetButton("Skill" + i))
			{
				if (!IsSignificantSkill(player.assignedSkills[i], player.stockSkill))
				{
					Player.SkillState stockSkill = player.stockSkill;
					player.stockSkill = player.assignedSkills[i];
					player.AssignSkillSlot(i, stockSkill.skillID);
					SoundManager.PlayAudio("Equip");
					parentHUD.cooldownUI.RefreshEntries();
					quickSwapCompleted = true;
					break;
				}
				SoundManager.PlayAudio("MenuError");
			}
		}
		return true;
	}
	if (!currentlySwapping)
	{
		skillSelectedBorder.transform.position = skillBorders[navigationIndex].transform.position;
		skillBorders[6].color = Color.white;
		swapText.gameObject.SetActive(value: false);
		swapPrompt.SetActive(value: true);
	}
	return false;
}

private void HandleNavigation()
{
	cursorVector = player.inputDevice.GetMoveVector();
	if (inputReceived && cursorVector.magnitude < 0.2f)
	{
		inputReceived = false;
	}
	else
	{
		if (inputReceived || !(cursorVector.magnitude > 0.3f))
		{
			return;
		}
		SoundManager.PlayAudio("MenuMove");
		inputReceived = true;
		if (Mathf.Abs(cursorVector.x) > Mathf.Abs(cursorVector.y))
		{
			if (navigationIndex != maxSkillCount)
			{
				navigationIndex = ChangeHorizontalIndex(navigationIndex, cursorVector.x > 0f);
				SelectSlot(navigationIndex);
			}
		}
		else if (cursorVector.y > 0f)
		{
			if (navigationIndex >= 0 && navigationIndex < maxSkillCount)
			{
				SwapFocus(takeFocus: false, giveNavIndex: false, 1);
				return;
			}
			if (navigationIndex == maxSkillCount)
			{
				navigationIndex = 5;
			}
			SelectSlot(navigationIndex);
		}
		else if (player.stockSkill != null && player.stockSkill.skillID != string.Empty && navigationIndex < maxSkillCount)
		{
			navigationIndex = maxSkillCount;
			SelectSlot(navigationIndex);
		}
		else if (!currentlySwapping)
		{
			bool giveNavIndex = navigationIndex < maxSkillCount;
			SwapFocus(takeFocus: false, giveNavIndex);
		}
	}
}

private int ChangeHorizontalIndex(int navIndex, bool increment)
{
	return (navIndex + (increment ? 1 : (-1)) + maxSkillCount) % maxSkillCount;
}

public void SelectSlot(int navIndex)
{
	if (currentlySwapping)
	{
		for (int i = 0; i < 7; i++)
		{
			if (i != skillToSwapIndex)
			{
				skillBorders[i].color = Color.white;
			}
		}
		swapText.gameObject.SetActive(value: true);
		swapPrompt.SetActive(value: false);
		if (skillToSwapIndex == maxSkillCount)
		{
			for (int j = 0; j < maxSkillCount; j++)
			{
				if (IsSignificantSkill(player.assignedSkills[j], player.stockSkill))
				{
					skillBorders[j].color = Vector4.one * 0.5f;
					skillIcons[j].color = Vector4.one * 0.5f;
				}
			}
		}
		else if (IsSignificantSkill(skillToSwap, player.stockSkill) && player.stockSkill != null && player.stockSkill.skillID != string.Empty)
		{
			skillBorders[6].color = Vector4.one * 0.5f;
			skillIcons[6].color = Vector4.one * 0.5f;
		}
	}
	else
	{
		swapText.gameObject.SetActive(value: false);
		swapPrompt.SetActive(value: true);
		for (int k = 0; k < 7; k++)
		{
			skillIcons[k].color = Color.white;
			skillBorders[k].color = ((k >= maxSkillCount || !IsSignificantSkill(player.assignedSkills[k])) ? Color.white : Color.gray);
		}
	}
	navigationIndex = navIndex;
	skillSelectedBorder.transform.position = skillBorders[navigationIndex].transform.position;
	if (hasFocus)
	{
		Player.SkillState skillState = null;
		skillState = ((navIndex >= maxSkillCount) ? player.stockSkill : player.assignedSkills[navIndex]);
		if (skillState != null)
		{
			infoText.text = "[<color=#FFCC00>" + TextManager.GetSkillName(skillState.skillID) + "</color>]\n" + TextManager.GetSkillDescription(skillState.skillID, skillState.IsEmpowered, skillState.element == ElementType.Chaos);
		}
		else
		{
			infoText.text = string.Empty;
		}
		SetSkillFlagImages(skillState);
	}
}

