		{
			return;
		}
		if (layerVertexData == null)
		{
			layerVertexData = new Dictionary<string, LayerVertexData>();
		}
		layerVertexData.Clear();
		for (int i = 0; i < Tile.tileLayerNames.Length; i++)
		{
			if (!layerVertexData.ContainsKey(Tile.tileLayerNames[i]))
			{
				layerVertexData[Tile.tileLayerNames[i]] = new LayerVertexData();
			}
			string text = Tile.tileLayerNames[i];
			layerVertexData[text].vertices = InitVertices(text, forceTileSet);
		}
	}

	public Vector3[] InitVertices(string tileLayerName, string forceTileSet = "")
	{
		List<Vector3> list = new List<Vector3>();
		int num = 0;
		for (int i = 0; i < RowCount; i++)
		{
			for (int j = 0; j < ColCount; j++)
			{
				if (!SkipTile(this[i, j], tileLayerName))
				{
					Vector3[] array = new Vector3[4]
					{
						new Vector3(j + 1, -i, 0f),
						new Vector3(j + 1, -i + -1, 0f),
						new Vector3(j, -i, 0f),
						new Vector3(j, -i + -1, 0f)
					};
					list.AddRange(array);
					this[i, j].vertices = array;
					string text = ((!(forceTileSet != string.Empty)) ? this[i, j].layers[tileLayerName].tileSetName : forceTileSet);
					layerVertexData[tileLayerName].tileSetNames.Add(text);
					if (!layerVertexData[tileLayerName].subMeshIndices.ContainsKey(text))
					{
						layerVertexData[tileLayerName].subMeshIndices[text] = new List<int>();
					}
					layerVertexData[tileLayerName].subMeshIndices[text].Add(num * 4);
		if (grid == null || (RowCount == 0 && ColCount == 0))
		{
			return 0;
		}
		int num = 0;
		for (int i = 0; i < RowCount; i++)
		{
			for (int j = 0; j < ColCount; j++)
			{
				if (this[i, j] != null)
				{
					num++;
				}
			}
		}
		return num;
	}

	public int CountTilesInDir(int row, int col, Func<Tile, bool> comparisonFunc, MapOrdinalDirections dir, bool excludeFirstTile = true, int maxTiles = 40, bool endOnFailure = true)
	{
		int num = 0;
		Vector2 directionalOffset = Globals.GetDirectionalOffset(dir);
		for (int i = 0; i < maxTiles; i++)
		{
			if (i == 0 && excludeFirstTile)
			{
				continue;
			}
			Vector2 vector = i * directionalOffset;
			int num2 = (int)((float)row + vector.x);
			int num3 = (int)((float)col + vector.y);
			if (!IsValidTile(num2, num3))
			{
				if (endOnFailure)
				{
					return num;
				}
			}
			else if (!comparisonFunc(this[num2, num3]))
			{
				if (endOnFailure)
				{
					return num;
				}
			}
			else
			{
				num++;
			}
		}
		return num;
	}
}

