	public static Tile.FloorType GetFloorType(TileGrid tileGrid, int row, int col, Func<Tile, bool> comparisonFunc)
	{
		if (!tileGrid.IsValidTile(row, col))
		{
			return Tile.FloorType.None;
		}
		MapOrdinalDirections mapOrdinalDirections = CheckAdjacentTiles(row, col, tileGrid, comparisonFunc);
		MapDirections mapDirections = Globals.OrdinalToCardinalDir(mapOrdinalDirections);
		Tile.FloorType floorType = (Tile.FloorType)mapDirections;
		if (floorType == Tile.FloorType.Center)
		{
			if (!mapOrdinalDirections.HasFlag(MapOrdinalDirections.NorthWest))
			{
				return Tile.FloorType.TopLeftCorner;
			}
			if (!mapOrdinalDirections.HasFlag(MapOrdinalDirections.NorthEast))
			{
				return Tile.FloorType.TopRightCorner;
			}
			if (!mapOrdinalDirections.HasFlag(MapOrdinalDirections.SouthWest))
			{
				return Tile.FloorType.BotLeftCorner;
			}
			if (!mapOrdinalDirections.HasFlag(MapOrdinalDirections.SouthEast))
			{
				return Tile.FloorType.BotRightCorner;
			}
		}
		return floorType;
	}
	public static MapOrdinalDirections GetAdjacentTerrainDirs(int tileRow, int tileCol, TileGrid tileGrid, Tile.TerrainType[] targetTerrains)
	{
		MapOrdinalDirections mapOrdinalDirections = MapOrdinalDirections.None;
		for (int i = 0; i < targetTerrains.Length; i++)
		{
			mapOrdinalDirections |= GetAdjacentTerrainDirs(tileRow, tileCol, tileGrid, targetTerrains[i]);
		}
		return mapOrdinalDirections;
	}
	public static MapOrdinalDirections GetAdjacentTerrainDirs(int tileRow, int tileCol, TileGrid tileGrid, Tile.TerrainType targetTerrain = Tile.TerrainType.Floor)
	{
		MapOrdinalDirections mapOrdinalDirections = MapOrdinalDirections.None;
		int colCount = tileGrid.ColCount;
		int rowCount = tileGrid.RowCount;
		if (tileRow < rowCount - 1 && tileGrid[tileRow + 1, tileCol] != null && tileGrid[tileRow + 1, tileCol].terrain == targetTerrain)
		{
			mapOrdinalDirections |= MapOrdinalDirections.South;
		}
		if (tileRow > 0 && tileGrid[tileRow - 1, tileCol] != null && tileGrid[tileRow - 1, tileCol].terrain == targetTerrain)
		{
			mapOrdinalDirections |= MapOrdinalDirections.North;

	if (tileRow < rowCount - 1 && tileCol > 0 && tileGrid[tileRow + 1, tileCol - 1] != null && tileGrid[tileRow + 1, tileCol - 1].terrain == targetTerrain)
	{
		mapOrdinalDirections |= MapOrdinalDirections.SouthWest;
	}
	if (tileRow < rowCount - 1 && tileCol < colCount - 1 && tileGrid[tileRow + 1, tileCol + 1] != null && tileGrid[tileRow + 1, tileCol + 1].terrain == targetTerrain)
	{
		mapOrdinalDirections |= MapOrdinalDirections.SouthEast;
	}
	if (tileRow > 0 && tileCol > 0 && tileGrid[tileRow - 1, tileCol - 1] != null && tileGrid[tileRow - 1, tileCol - 1].terrain == targetTerrain)
	{
		mapOrdinalDirections |= MapOrdinalDirections.NorthWest;
	}
	if (tileRow > 0 && tileCol < colCount - 1 && tileGrid[tileRow - 1, tileCol + 1] != null && tileGrid[tileRow - 1, tileCol + 1].terrain == targetTerrain)
	{
		mapOrdinalDirections |= MapOrdinalDirections.NorthEast;
	}
	return mapOrdinalDirections;
}
public virtual int TerrainTypeToTileSetID(Tile.TerrainType terrain, int tileRow, int tileCol, TileGrid tileGrid)
{
	switch (terrain)
	{
	case Tile.TerrainType.Wall:
		if (!tileGrid[tileRow, tileCol].layers["Wall"].hasDoodad && !tileGrid[tileRow, tileCol].layers["Wall"].flipX)
		{
			tileGrid[tileRow, tileCol].layers["Wall"].flipX = UnityEngine.Random.value < 0.5f;
		}
		if (tileRow < tileGrid.RowCount - 1 && tileGrid[tileRow + 1, tileCol] != null && tileGrid[tileRow + 1, tileCol].terrain == Tile.TerrainType.Floor)
		{
			return lowerWallTiles.GetRandomValue();
		}
		if (tileRow < tileGrid.RowCount - 2 && tileGrid[tileRow + 2, tileCol] != null && (tileGrid[tileRow + 2, tileCol].terrain == Tile.TerrainType.Floor || tileGrid[tileRow + 2, tileCol].terrain == Tile.TerrainType.Pit))
		{
			return midWallTiles.GetRandomValue();
		}
		if (tileRow < tileGrid.RowCount - 3 && tileGrid[tileRow + 3, tileCol] != null && (tileGrid[tileRow + 3, tileCol].terrain == Tile.TerrainType.Floor || tileGrid[tileRow + 3, tileCol].terrain == Tile.TerrainType.Pit))
		{
			return topWallTiles.GetRandomValue();
		}
		return wallTiles.GetRandomValue();
	case Tile.TerrainType.Floor:
		return FloorToTileSetID(tileRow, tileCol, tileGrid);
	case Tile.TerrainType.Pit:
		return PitToTileSetID(tileRow, tileCol, tileGrid);
	default:
		return transparentTile;
	}
}
public int PathFloorToTileSetID(int tileRow, int tileCol, TileGrid tileGrid)
{
	int result = -1;
