	{
		return result;
	}
	Tile tile = tileGrid[tileRow, tileCol];
	string pathTileSetID = tile.pathTileSetID;
	string key = pathTileSetID + "-pit";
	if (!pathTileSets.ContainsKey(pathTileSetID))
	{
		tile.path = Tile.FloorType.None;
		return result;
	}
	PathTileSet pathTileSet = pathTileSets[pathTileSetID];
	PathTileSet pathTileSet2 = null;
	if (pathTileSets.ContainsKey(key))
	{
		pathTileSet2 = pathTileSets[key];
	}
	switch (tile.path)
	{
	case Tile.FloorType.Top:
		result = pathTileSet.topPathTiles.GetRandomValue();
		num = pathTileSet2?.topPathTiles.GetRandomValue() ?? (-1);
		break;
	case Tile.FloorType.TopLeft:
		result = pathTileSet.topLeftPathTile.GetRandomValue();
		num = pathTileSet2?.topLeftPathTile.GetRandomValue() ?? (-1);
		break;
	case Tile.FloorType.TopRight:
		result = pathTileSet.topRightPathTile.GetRandomValue();
		num = pathTileSet2?.topRightPathTile.GetRandomValue() ?? (-1);
		break;
	case Tile.FloorType.Left:
		result = pathTileSet.leftPathTiles.GetRandomValue();
		num = pathTileSet2?.leftPathTiles.GetRandomValue() ?? (-1);
		break;
